const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const easternPoint = ee.Geometry.Point([-137.527803, 48.504441]);
  const westernPoint = ee.Geometry.Point([-169.318365, 46.750838]);
  const sstBand = 'sst';
  const dataCollection = 'NOAA/CDR/OISST/V2.1';

  const comparisonStart = '2016-01-01';
  const comparisonEnd = '2016-01-31';

  const baselineStartYear = 2003;
  const baselineEndYear = 2012;

  // 2. Data Acquisition & Check
  // Function to get monthly means for a given year
  const getJanMean = (year) => {
    const startDate = ee.Date.fromYMD(year, 1, 1);
    const endDate = startDate.advance(1, 'month');
    return ee.ImageCollection(dataCollection)
      .filterDate(startDate, endDate)
      .select(sstBand)
      .mean()
      .set('year', year);
  };

  // Baseline data
  const baselineYears = ee.List.sequence(baselineStartYear, baselineEndYear);
  const baselineCollection = ee.ImageCollection.fromImages(baselineYears.map(getJanMean));
  const baselineSize = baselineCollection.size().getInfo();
  if (baselineSize === 0) {
      console.log(`No images found for baseline period ${baselineStartYear}-${baselineEndYear}.`);
      console.log('A'); // A is a placeholder here, the final tag will be on the last line.
      console.log('C1');
      return;
  }

  // Comparison data
  const comparisonCollection = ee.ImageCollection(dataCollection)
    .filterDate(comparisonStart, comparisonEnd)
    .select(sstBand);
  const comparisonSize = comparisonCollection.size().getInfo();
  if (comparisonSize === 0) {
      console.log(`No images found for comparison period ${comparisonStart} to ${comparisonEnd}.`);
      console.log('A'); // Placeholder
      console.log('C1');
      return;
  }

  // 3. Processing
  const baselineMeanSST = baselineCollection.mean();
  const comparisonMeanSST = comparisonCollection.mean();
  const anomalyImage = comparisonMeanSST.subtract(baselineMeanSST);

  // 4. Calculation
  const scale = 1000; // OISST resolution is ~27.8km, 1km is safe.
  const easternAnomaly = anomalyImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: easternPoint,
    scale: scale,
  }).get(sstBand);

  const westernAnomaly = anomalyImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: westernPoint,
    scale: scale,
  }).get(sstBand);

  // Execute computations
  const easternVal = easternAnomaly.getInfo();
  const westernVal = westernAnomaly.getInfo();

  // 5. Validation & Final Answer
  console.log(`Baseline collection size (years): ${baselineSize}`);
  console.log(`Comparison collection size (days): ${comparisonSize}`);

  if (easternVal === null || westernVal === null) {
      console.log('Could not extract valid pixel values for one or both points.');
      console.log(`Eastern Anomaly: ${easternVal}, Western Anomaly: ${westernVal}`);
      if (easternVal === null && westernVal === null) {
          console.log('C2');
      } else {
          console.log('C3');
      }
      return;
  }

  // OISST values are scaled by 100, so anomalies are also scaled.
  // Converting to degrees Celsius for interpretability in print statements.
  const easternAnomalyC = easternVal / 100.0;
  const westernAnomalyC = westernVal / 100.0;

  console.log(`Eastern Location Anomaly (2016 vs 2003-2012): ${easternAnomalyC.toFixed(2)} C`);
  console.log(`Western Location Anomaly (2016 vs 2003-2012): ${westernAnomalyC.toFixed(2)} C`);

  if (easternAnomalyC > westernAnomalyC) {
    console.log('Evidence: Eastern anomaly is higher than the western anomaly.');
    console.log('A');
  } else {
    console.log('Evidence: Eastern anomaly is not higher than the western anomaly.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D');
});
